async function authMemberById(env,id){return d1First(env.MEMBERS_DB.prepare("SELECT id,email,display_name,role,status,marketing_status,tier,email_verified_at,created_at,updated_at,last_login_at FROM members WHERE id=? AND status <> 'deleted' LIMIT 1").bind(id))}
async function authCreateSession(env,memberId){const rawToken=authBase64Url(authBytes(32));const sessionHash=await authHash(rawToken);const now=new Date();const expiresAt=new Date(now.getTime()+30*24*60*60*1000).toISOString();await env.MEMBERS_DB.prepare("INSERT INTO member_sessions (id,member_id,session_hash,expires_at,created_at,last_seen_at) VALUES (?,?,?,?,?,?)").bind(authId('session'),memberId,sessionHash,expiresAt,now.toISOString(),now.toISOString()).run();await env.MEMBERS_DB.prepare("UPDATE members SET last_login_at=?,updated_at=? WHERE id=?").bind(now.toISOString(),now.toISOString(),memberId).run();return{rawToken,expiresAt}}
async function authSessionMember(request,env){if(!hasMembersDb(env))return null;const rawToken=authCookieValue(request);if(!rawToken)return null;const sessionHash=await authHash(rawToken);const now=new Date().toISOString();const session=await d1First(env.MEMBERS_DB.prepare("SELECT id,member_id,expires_at,revoked_at FROM member_sessions WHERE session_hash=? LIMIT 1").bind(sessionHash));if(!session||session.revoked_at||String(session.expires_at||'')<=now)return null;const member=await authMemberById(env,session.member_id);if(!member||member.status!=='active')return null;await env.MEMBERS_DB.prepare("UPDATE member_sessions SET last_seen_at=? WHERE id=?").bind(now,session.id).run().catch(()=>null);return{session,member}}
async function handleAuthRequestLink(request,env){
  const body=await readBody(request);
  const email=cleanText(body.email||'',240).toLowerCase();
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return json({ok:false,error:'Valid email required'},400);
  if(!hasMembersDb(env))return json({ok:false,configured:false,error:'Membership database unavailable'},503);
  if(!authMailConfigured(env))return json({ok:false,configured:false,error:'Transactional email delivery is not configured'},503);
  const member=await authMemberByEmail(env,email);
  if(member){
    const purpose=member.email_verified_at?'login':'verify_email';
    const delivery=await authIssueLink(request,env,member,purpose);
    await env.MEMBERS_DB.prepare("INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)").bind(authId('audit'),member.id,'auth.magic_link.delivery','member',member.id,JSON.stringify({purpose,sent:Boolean(delivery.sent),configured:Boolean(delivery.configured),providerStatus:delivery.status||null,messageId:delivery.messageId||null,error:delivery.error||null,payloadLengths:delivery.payloadLengths||null,requestRef:delivery.requestRef||null,requestedAt:delivery.requestedAt||null}),new Date().toISOString()).run().catch(()=>null);
  }
  return json({ok:true,accepted:true,message:'If a matching member account exists, a complete one-time login email has been sent.'},202)
}
async function handleAuthVerify(request,env){const url=new URL(request.url);const rawToken=cleanText(url.searchParams.get('token')||'',300);const requestedPurpose=cleanText(url.searchParams.get('purpose')||'',40);const failure=reason=>new Response(null,{status:303,headers:{...securityHeaders,Location:authOrigin(request)+'/member-login.html?error='+encodeURIComponent(reason),'Cache-Control':'no-store'}});if(!hasMembersDb(env)||!rawToken)return failure('invalid-link');const tokenHash=await authHash(rawToken);const record=await d1First(env.MEMBERS_DB.prepare("SELECT id,member_id,purpose,expires_at,used_at FROM magic_links WHERE token_hash=? LIMIT 1").bind(tokenHash));const now=new Date().toISOString();if(!record||record.used_at||String(record.expires_at||'')<=now||record.purpose!==requestedPurpose)return failure('expired-or-used');const member=await authMemberById(env,record.member_id);if(!member)return failure('member-not-found');if(record.purpose==='verify_email'){await env.MEMBERS_DB.prepare("UPDATE members SET status='active',marketing_status=CASE WHEN marketing_status='suppressed' THEN marketing_status ELSE 'subscribed' END,email_verified_at=COALESCE(email_verified_at,?),updated_at=? WHERE id=?").bind(now,now,member.id).run()}else if(record.purpose!=='login')return failure('invalid-purpose');await env.MEMBERS_DB.prepare("UPDATE magic_links SET used_at=? WHERE id=?").bind(now,record.id).run();const session=await authCreateSession(env,member.id);const destination=authOrigin(request)+'/member-dashboard.html?'+(record.purpose==='verify_email'?'verified=1':'login=1');return new Response(null,{status:303,headers:{...securityHeaders,Location:destination,'Set-Cookie':authSessionCookie(session.rawToken),'Cache-Control':'no-store'}})}
async function handleAuthLogout(request,env){const rawToken=authCookieValue(request);if(rawToken&&hasMembersDb(env)){const sessionHash=await authHash(rawToken);await env.MEMBERS_DB.prepare("UPDATE member_sessions SET revoked_at=? WHERE session_hash=? AND revoked_at IS NULL").bind(new Date().toISOString(),sessionHash).run().catch(()=>null)}return new Response(JSON.stringify({ok:true,authenticated:false}),{status:200,headers:{...jsonHeaders,'Set-Cookie':authClearCookie()}})}
async function handleMemberMe(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);const subscription=await d1First(env.MEMBERS_DB.prepare("SELECT provider,provider_subscription_id,provider_plan_id,tier,status,next_billing_at,current_period_end,cancel_at_period_end FROM subscriptions WHERE member_id=? ORDER BY updated_at DESC LIMIT 1").bind(auth.member.id));return json({ok:true,authenticated:true,member:{id:auth.member.id,email:auth.member.email,displayName:auth.member.display_name||'',role:auth.member.role||'member',tier:auth.member.tier,status:auth.member.status,marketingStatus:auth.member.marketing_status,emailVerifiedAt:auth.member.email_verified_at,createdAt:auth.member.created_at,lastLoginAt:auth.member.last_login_at},subscription:subscription||null,paidAccessEnabled:false,paymentProvider:'paypal-pending'})}
async function handleAuthHealth(env){let schemaReady=false;let members=0;if(hasMembersDb(env)){try{const row=await env.MEMBERS_DB.prepare("SELECT COUNT(*) AS count FROM members").first();members=Number(row&&row.count||0);await env.MEMBERS_DB.prepare("SELECT COUNT(*) AS count FROM magic_links").first();await env.MEMBERS_DB.prepare("SELECT COUNT(*) AS count FROM member_sessions").first();schemaReady=true}catch{schemaReady=false}}return json({ok:schemaReady,d1Connected:hasMembersDb(env),authSchemaReady:schemaReady,transactionalEmailConfigured:authMailConfigured(env),provider:'brevo',members,magicLinkMinutes:15,sessionDays:30,endpoints:{signup:'/api/membership/signup',requestLink:'/api/auth/request-link',verify:'/api/auth/verify',logout:'/api/auth/logout',me:'/api/member/me'},updatedAt:new Date().toISOString()})}

/* paypal-membership-v1: verified subscriptions, checkout intents, signed webhooks, automatic entitlements */
function paypalEnvironment(env){return String(env&&env.PAYPAL_ENVIRONMENT||'sandbox').toLowerCase()==='live'?'live':'sandbox'}
function paypalApiBase(env){return paypalEnvironment(env)==='live'?'https://api-m.paypal.com':'https://api-m.sandbox.paypal.com'}
function paypalPlans(env){return{supporter:String(env&&env.PAYPAL_PLAN_SUPPORTER||''),intelligence:String(env&&env.PAYPAL_PLAN_INTELLIGENCE||''),research_pro:String(env&&env.PAYPAL_PLAN_RESEARCH_PRO||'')}}
function paypalTierForPlan(env,planId){const plans=paypalPlans(env);for(const tier of Object.keys(plans)){if(plans[tier]&&plans[tier]===String(planId||''))return tier}return''}
function paypalConfigured(env){const plans=paypalPlans(env);return Boolean(env&&env.PAYPAL_CLIENT_ID&&env.PAYPAL_CLIENT_SECRET&&env.PAYPAL_WEBHOOK_ID&&plans.supporter&&plans.intelligence&&plans.research_pro)}
function paypalSafeStatus(value){return cleanText(value||'UNKNOWN',40).toUpperCase().replace(/[^A-Z_]/g,'_')}
function paypalPaidStatus(value){return paypalSafeStatus(value)==='ACTIVE'}
async function paypalAccessToken(env){if(!env||!env.PAYPAL_CLIENT_ID||!env.PAYPAL_CLIENT_SECRET)throw new Error('PayPal credentials are not configured');const credentials=btoa(String(env.PAYPAL_CLIENT_ID)+':'+String(env.PAYPAL_CLIENT_SECRET));const response=await fetch(paypalApiBase(env)+'/v1/oauth2/token',{method:'POST',headers:{Authorization:'Basic '+credentials,'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body:'grant_type=client_credentials'});const text=await response.text();let payload={};try{payload=JSON.parse(text||'{}')}catch{}if(!response.ok||!payload.access_token)throw new Error(cleanText(payload.error_description||payload.error||text||'PayPal OAuth failed',500));return payload.access_token}
async function paypalRequest(env,pathname,options={}){const token=await paypalAccessToken(env);const headers={Authorization:'Bearer '+token,Accept:'application/json','Content-Type':'application/json',...(options.headers||{})};const response=await fetch(paypalApiBase(env)+pathname,{...options,headers});const text=await response.text();let payload={};if(text){try{payload=JSON.parse(text)}catch{payload={raw:text}}}if(!response.ok)throw new Error(cleanText(payload.message||payload.error_description||payload.name||text||('PayPal HTTP '+response.status),700));return{status:response.status,payload}}
async function paypalSubscriptionDetails(env,subscriptionId){const safeId=encodeURIComponent(cleanText(subscriptionId,120));return(await paypalRequest(env,'/v1/billing/subscriptions/'+safeId,{method:'GET'})).payload}
async function paypalCurrentSubscription(env,memberId){return d1First(env.MEMBERS_DB.prepare("SELECT id,member_id,provider,provider_customer_id,provider_subscription_id,provider_plan_id,tier,status,last_payment_at,next_billing_at,current_period_end,cancel_at_period_end,suspended_at,cancelled_at,created_at,updated_at FROM subscriptions WHERE member_id=? AND provider='paypal' ORDER BY updated_at DESC LIMIT 1").bind(memberId))}
async function paypalRecalculateTier(env,memberId){const active=await d1First(env.MEMBERS_DB.prepare("SELECT tier FROM subscriptions WHERE member_id=? AND provider='paypal' AND status='ACTIVE' ORDER BY updated_at DESC LIMIT 1").bind(memberId));const tier=active&&active.tier?active.tier:'free';await env.MEMBERS_DB.prepare('UPDATE members SET tier=?,updated_at=? WHERE id=?').bind(tier,new Date().toISOString(),memberId).run();return tier}
async function paypalSyncSubscription(env,details,memberId){const subscriptionId=cleanText(details&&details.id||'',120);const planId=cleanText(details&&details.plan_id||'',120);const tier=paypalTierForPlan(env,planId);if(!subscriptionId||!tier)throw new Error('PayPal subscription does not match a configured membership plan');const status=paypalSafeStatus(details.status);const now=new Date().toISOString();const payerId=cleanText(details&&details.subscriber&&details.subscriber.payer_id||'',120);const billing=details&&details.billing_info||{};const nextBillingAt=cleanText(billing.next_billing_time||'',80)||null;const lastPaymentAt=cleanText(billing.last_payment&&billing.last_payment.time||'',80)||null;const suspendedAt=status==='SUSPENDED'?now:null;const cancelledAt=(status==='CANCELLED'||status==='EXPIRED')?now:null;const existing=await d1First(env.MEMBERS_DB.prepare('SELECT id,member_id,created_at FROM subscriptions WHERE provider_subscription_id=? LIMIT 1').bind(subscriptionId));if(existing&&existing.member_id!==memberId)throw new Error('PayPal subscription is already attached to another member');if(existing){await env.MEMBERS_DB.prepare("UPDATE subscriptions SET provider_customer_id=?,provider_plan_id=?,tier=?,status=?,last_payment_at=COALESCE(?,last_payment_at),next_billing_at=?,current_period_end=?,cancel_at_period_end=?,suspended_at=COALESCE(?,suspended_at),cancelled_at=COALESCE(?,cancelled_at),updated_at=? WHERE id=?").bind(payerId||null,planId,tier,status,lastPaymentAt,nextBillingAt,nextBillingAt,status==='CANCELLED'?1:0,suspendedAt,cancelledAt,now,existing.id).run()}else{await env.MEMBERS_DB.prepare("INSERT INTO subscriptions (id,member_id,provider,provider_customer_id,provider_subscription_id,provider_plan_id,tier,status,last_payment_at,next_billing_at,current_period_end,cancel_at_period_end,suspended_at,cancelled_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind('subscription-'+crypto.randomUUID(),memberId,'paypal',payerId||null,subscriptionId,planId,tier,status,lastPaymentAt,nextBillingAt,nextBillingAt,status==='CANCELLED'?1:0,suspendedAt,cancelledAt,now,now).run()}const effectiveTier=await paypalRecalculateTier(env,memberId);return{provider:'paypal',subscriptionId,planId,tier,status,paidAccess:paypalPaidStatus(status),effectiveTier,lastPaymentAt,nextBillingAt}}
async function handlePayPalConfig(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);const plans=paypalPlans(env);return json({ok:true,authenticated:true,configured:paypalConfigured(env),environment:paypalEnvironment(env),currency:'EUR',clientId:paypalConfigured(env)?String(env.PAYPAL_CLIENT_ID):null,plans:paypalConfigured(env)?plans:{supporter:'',intelligence:'',research_pro:''},tiers:{supporter:{price:'9.00',label:'Supporter'},intelligence:{price:'19.00',label:'Intelligence Member'},research_pro:{price:'49.00',label:'Research Pro'}},webhookConfigured:Boolean(env&&env.PAYPAL_WEBHOOK_ID)})}
async function handlePayPalCheckoutIntent(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);if(!hasMembersDb(env)||!paypalConfigured(env))return json({ok:false,configured:false,error:'PayPal subscriptions are not configured'},503);const body=await readBody(request);const tier=cleanText(body.tier||'',40);const plans=paypalPlans(env);const planId=plans[tier]||'';if(!planId)return json({ok:false,error:'Unknown membership tier'},400);const now=new Date();const expiresAt=new Date(now.getTime()+30*60*1000).toISOString();await env.MEMBERS_DB.prepare('UPDATE paypal_checkout_intents SET used_at=? WHERE member_id=? AND tier=? AND used_at IS NULL').bind(now.toISOString(),auth.member.id,tier).run();const intentId='paypal-intent-'+crypto.randomUUID();await env.MEMBERS_DB.prepare('INSERT INTO paypal_checkout_intents (id,member_id,tier,plan_id,expires_at,created_at) VALUES (?,?,?,?,?,?)').bind(intentId,auth.member.id,tier,planId,expiresAt,now.toISOString()).run();return json({ok:true,configured:true,intentId,tier,planId,expiresAt,currency:'EUR'})}
async function handlePayPalConfirm(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);if(!hasMembersDb(env)||!paypalConfigured(env))return json({ok:false,configured:false,error:'PayPal subscriptions are not configured'},503);const body=await readBody(request);const subscriptionId=cleanText(body.subscriptionId||'',120);const intentId=cleanText(body.checkoutIntentId||'',120);if(!subscriptionId||!intentId)return json({ok:false,error:'Subscription ID and checkout intent are required'},400);const intent=await d1First(env.MEMBERS_DB.prepare('SELECT id,member_id,tier,plan_id,expires_at,used_at FROM paypal_checkout_intents WHERE id=? LIMIT 1').bind(intentId));const now=new Date().toISOString();if(!intent||intent.member_id!==auth.member.id||intent.used_at||String(intent.expires_at||'')<=now)return json({ok:false,error:'Checkout intent is invalid or expired'},400);const details=await paypalSubscriptionDetails(env,subscriptionId);if(String(details.id||'')!==subscriptionId||String(details.plan_id||'')!==intent.plan_id||String(details.custom_id||'')!==intent.id)return json({ok:false,error:'PayPal subscription verification failed'},400);const status=paypalSafeStatus(details.status);if(!['APPROVAL_PENDING','APPROVED','ACTIVE'].includes(status))return json({ok:false,error:'PayPal subscription is not approved'},409);const subscription=await paypalSyncSubscription(env,details,auth.member.id);await env.MEMBERS_DB.prepare('UPDATE paypal_checkout_intents SET used_at=? WHERE id=?').bind(now,intent.id).run();await env.MEMBERS_DB.prepare('INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').bind('audit-'+crypto.randomUUID(),auth.member.id,'paypal_subscription_confirmed','subscription',subscription.subscriptionId,JSON.stringify({tier:subscription.tier,status:subscription.status}),now).run();return json({ok:true,verified:true,subscription,paidAccess:subscription.paidAccess,message:subscription.paidAccess?'PayPal membership is active.':'PayPal approved the subscription; access will activate when PayPal reports ACTIVE.'})}
async function handlePayPalStatus(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);const subscription=hasMembersDb(env)?await paypalCurrentSubscription(env,auth.member.id):null;return json({ok:true,authenticated:true,configured:paypalConfigured(env),environment:paypalEnvironment(env),subscription:subscription||null,paidAccess:Boolean(subscription&&paypalPaidStatus(subscription.status)),tier:auth.member.tier||'free'})}
async function handlePayPalCancel(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);if(!paypalConfigured(env))return json({ok:false,configured:false,error:'PayPal subscriptions are not configured'},503);const subscription=await paypalCurrentSubscription(env,auth.member.id);if(!subscription||!subscription.provider_subscription_id)return json({ok:false,error:'No PayPal subscription found'},404);if(['CANCELLED','EXPIRED'].includes(paypalSafeStatus(subscription.status)))return json({ok:true,alreadyCancelled:true,subscription});await paypalRequest(env,'/v1/billing/subscriptions/'+encodeURIComponent(subscription.provider_subscription_id)+'/cancel',{method:'POST',body:JSON.stringify({reason:'Cancelled by member through Matrix Reprogrammed'})});const now=new Date().toISOString();await env.MEMBERS_DB.prepare("UPDATE subscriptions SET status='CANCELLED',cancel_at_period_end=1,cancelled_at=?,updated_at=? WHERE id=?").bind(now,now,subscription.id).run();await paypalRecalculateTier(env,auth.member.id);return json({ok:true,cancelled:true,subscriptionId:subscription.provider_subscription_id,paidAccess:false})}
function paypalWebhookHeaders(request){return{auth_algo:request.headers.get('paypal-auth-algo')||'',cert_url:request.headers.get('paypal-cert-url')||'',transmission_id:request.headers.get('paypal-transmission-id')||'',transmission_sig:request.headers.get('paypal-transmission-sig')||'',transmission_time:request.headers.get('paypal-transmission-time')||''}}
async function paypalVerifyWebhook(request,env,event){const h=paypalWebhookHeaders(request);if(!h.auth_algo||!h.cert_url||!h.transmission_id||!h.transmission_sig||!h.transmission_time||!env.PAYPAL_WEBHOOK_ID)return false;const result=await paypalRequest(env,'/v1/notifications/verify-webhook-signature',{method:'POST',body:JSON.stringify({...h,webhook_id:String(env.PAYPAL_WEBHOOK_ID),webhook_event:event})});return String(result.payload&&result.payload.verification_status||'').toUpperCase()==='SUCCESS'}
function paypalWebhookSubscriptionId(event){const resource=event&&event.resource||{};if(/^BILLING\.SUBSCRIPTION\./.test(String(event&&event.event_type||'')))return cleanText(resource.id||'',120);return cleanText(resource.billing_agreement_id||resource.supplementary_data&&resource.supplementary_data.related_ids&&resource.supplementary_data.related_ids.subscription_id||'',120)}
async function handlePayPalWebhook(request,env){if(!hasMembersDb(env)||!paypalConfigured(env))return json({ok:false,configured:false,error:'PayPal webhook processing is not configured'},503);const raw=await request.text();let event={};try{event=JSON.parse(raw)}catch{return json({ok:false,error:'Invalid PayPal webhook JSON'},400)}const verified=await paypalVerifyWebhook(request,env,event).catch(()=>false);if(!verified)return json({ok:false,error:'PayPal webhook signature verification failed'},400);const eventId=cleanText(event.id||'',160);const eventType=cleanText(event.event_type||'',160);if(!eventId||!eventType)return json({ok:false,error:'PayPal webhook event ID and type are required'},400);const duplicate=await d1First(env.MEMBERS_DB.prepare('SELECT id,processing_status FROM payment_webhook_events WHERE provider_event_id=? LIMIT 1').bind(eventId));if(duplicate)return json({ok:true,verified:true,duplicate:true,eventId});const receivedAt=new Date().toISOString();await env.MEMBERS_DB.prepare('INSERT INTO payment_webhook_events (id,provider,provider_event_id,event_type,payload_json,received_at,processing_status) VALUES (?,?,?,?,?,?,?)').bind('webhook-'+crypto.randomUUID(),'paypal',eventId,eventType,raw,receivedAt,'pending').run();try{const subscriptionId=paypalWebhookSubscriptionId(event);let processingStatus='unmatched';if(subscriptionId){let stored=await d1First(env.MEMBERS_DB.prepare('SELECT member_id FROM subscriptions WHERE provider_subscription_id=? LIMIT 1').bind(subscriptionId));if(!stored){const customId=cleanText(event&&event.resource&&event.resource.custom_id||'',160);if(customId)stored=await d1First(env.MEMBERS_DB.prepare('SELECT member_id FROM paypal_checkout_intents WHERE id=? LIMIT 1').bind(customId))}if(stored&&stored.member_id){const details=await paypalSubscriptionDetails(env,subscriptionId);await paypalSyncSubscription(env,details,stored.member_id);if(eventType==='PAYMENT.SALE.COMPLETED'){const paidAt=cleanText(event&&event.resource&&event.resource.create_time||receivedAt,80);await env.MEMBERS_DB.prepare('UPDATE subscriptions SET last_payment_at=?,updated_at=? WHERE provider_subscription_id=?').bind(paidAt,receivedAt,subscriptionId).run()}processingStatus='processed'}}await env.MEMBERS_DB.prepare('UPDATE payment_webhook_events SET processed_at=?,processing_status=? WHERE provider_event_id=?').bind(new Date().toISOString(),processingStatus,eventId).run();return json({ok:true,verified:true,eventId,eventType,processingStatus})}catch(error){await env.MEMBERS_DB.prepare('UPDATE payment_webhook_events SET processed_at=?,processing_status=?,error_message=? WHERE provider_event_id=?').bind(new Date().toISOString(),'error',cleanText(error&&error.message,700),eventId).run();return json({ok:false,verified:true,error:'PayPal webhook processing failed'},500)}}
async function handlePayPalHealth(env){let schemaReady=false;let subscriptions=0;let checkoutIntents=0;let webhookEvents=0;if(hasMembersDb(env)){try{const a=await env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM subscriptions').first();const b=await env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM paypal_checkout_intents').first();const c=await env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM payment_webhook_events').first();subscriptions=Number(a&&a.count||0);checkoutIntents=Number(b&&b.count||0);webhookEvents=Number(c&&c.count||0);schemaReady=true}catch{schemaReady=false}}const plans=paypalPlans(env);return json({ok:schemaReady,d1Connected:hasMembersDb(env),paypalSchemaReady:schemaReady,configured:paypalConfigured(env),environment:paypalEnvironment(env),clientIdConfigured:Boolean(env&&env.PAYPAL_CLIENT_ID),clientSecretConfigured:Boolean(env&&env.PAYPAL_CLIENT_SECRET),webhookConfigured:Boolean(env&&env.PAYPAL_WEBHOOK_ID),plansConfigured:{supporter:Boolean(plans.supporter),intelligence:Boolean(plans.intelligence),researchPro:Boolean(plans.research_pro)},currency:'EUR',subscriptions,checkoutIntents,webhookEvents,paidAccessPolicy:'ACTIVE subscriptions only',updatedAt:new Date().toISOString()})}
async function handlePayPalMemberMe(request,env){const auth=await authSessionMember(request,env);if(!auth)return json({ok:false,authenticated:false,error:'Authentication required'},401);const subscription=hasMembersDb(env)?await paypalCurrentSubscription(env,auth.member.id):null;const paidAccess=Boolean(subscription&&paypalPaidStatus(subscription.status));return json({ok:true,authenticated:true,member:{id:auth.member.id,email:auth.member.email,displayName:auth.member.display_name||'',role:auth.member.role||'member',tier:auth.member.tier,status:auth.member.status,marketingStatus:auth.member.marketing_status,emailVerifiedAt:auth.member.email_verified_at,createdAt:auth.member.created_at,lastLoginAt:auth.member.last_login_at},subscription:subscription||null,paidAccessEnabled:paidAccess,paymentProvider:'paypal',paypalConfigured:paypalConfigured(env)})}

