function assetResponse(response,pathname=''){const headers=new Headers(response.headers);for(const[k,v]of Object.entries(securityHeaders))headers.set(k,v);headers.set('X-Matrix-Origin','worker-assets');headers.set('X-Matrix-Asset-Path',pathname);if(pathname==='/'||pathname.endsWith('.html')||!(/\.[a-z0-9]{2,8}$/i.test(pathname)))headers.set('Cache-Control',cacheHeadersForPath(pathname));return new Response(response.body,{status:response.status,statusText:response.statusText,headers})}
