function assetCandidates(originalPath,routedPath){const out=[];const add=x=>{if(x&&!out.includes(x))out.push(x)};add(routedPath);add(originalPath);if(routedPath==='/'||originalPath==='/')add('/index.html');if(!routedPath.endsWith('/')){add(`${routedPath}.html`);add(`${routedPath}/index.html`)}if(routedPath.endsWith('/')){add(`${routedPath}index.html`);add(`${routedPath.replace(/\/$/,'')}.html`)}add('/404.html');return out}

