const osintToolPolicies={holehe:{label:'Email account signals',access:'member',minimumTier:'registered',dailyLimit:5},spiderfoot:{label:'Passive digital footprint scan',access:'member',minimumTier:'intelligence_6',dailyLimit:2},h8mail:{label:'Breach exposure review',access:'member',minimumTier:'intelligence_6',selfOnlyForMembers:true,dailyLimit:10}};
function osintRole(member){return cleanText(member&&member.role||'member',40).toLowerCase()}
function osintIsAdmin(member){return osintRole(member)==='admin'}const osintTierRank={anonymous:0,registered:1,supporter_3:2,intelligence_6:3,research_pro_9:4,admin:99};const osintTierAlias={free:'registered',registered:'registered',supporter:'supporter_3',supporter_3:'supporter_3',intelligence:'intelligence_6',intelligence_6:'intelligence_6',research_pro:'research_pro_9',research_pro_9:'research_pro_9'};async function osintEffectiveTier(env,member){if(osintIsAdmin(member))return'admin';const row=await d1First(env.MEMBERS_DB.prepare('SELECT effective_tier,tier_rank FROM member_effective_entitlements WHERE member_id=? LIMIT 1').bind(member.id));return osintTierAlias[String(row&&row.effective_tier||member.tier||'free').toLowerCase()]||'registered'}function osintTierAllowed(current,required){return Number(osintTierRank[current]||0)>=Number(osintTierRank[required]||99)}
function osintValidEmail(value){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value||''))}
function osintConfigured(env){return Boolean(hasMembersDb(env)&&env&&env.OSINT_DATA_KEY&&env.OSINT_RUNNER_TOKEN)}
function osintRunnerToken(request){const auth=request.headers.get('authorization')||'';return auth.toLowerCase().startsWith('bearer ')?auth.slice(7).trim():''}
function osintRunnerAuthorized(request,env){return Boolean(env&&env.OSINT_RUNNER_TOKEN&&secureEqual(osintRunnerToken(request),String(env.OSINT_RUNNER_TOKEN)))}
function osintBytesToB64(bytes){let binary='';for(const byte of new Uint8Array(bytes))binary+=String.fromCharCode(byte);return btoa(binary)}
function osintB64ToBytes(value){const binary=atob(String(value||''));const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes}
async function osintCryptoKey(env){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(env.OSINT_DATA_KEY||'')));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM'},false,['encrypt','decrypt'])}
