async function osintAudit(env,memberId,action,targetId,metadata={}){if(!hasMembersDb(env))return;const now=new Date().toISOString();await env.MEMBERS_DB.prepare('INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').bind('audit-'+crypto.randomUUID(),memberId||'osint-runner',action,'osint_tool_job',targetId,JSON.stringify(metadata),now).run().catch(()=>null)}
function osintSanitizeResult(value,key='',depth=0){if(depth>6)return'[depth-limited]';const blocked=/(?:password|passwd|credential|secret|token|api.?key|recovery|phone|mobile|salt|raw|cleartext|session|cookie|authorization|target|email|hash|ip(?:address)?)/i;if(blocked.test(String(key||'')))return undefined;if(value===null||value===undefined)return value;if(typeof value==='string')return cleanText(value.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[redacted-email]').replace(/\+?\d[\d ()-]{7,}\d/g,'[redacted-phone]'),700);if(typeof value==='number'||typeof value==='boolean')return value;if(Array.isArray(value))return value.slice(0,200).map(item=>osintSanitizeResult(item,'item',depth+1)).filter(item=>item!==undefined);if(typeof value==='object'){const out={};for(const [childKey,child] of Object.entries(value).slice(0,100)){const safe=osintSanitizeResult(child,childKey,depth+1);if(safe!==undefined)out[cleanText(childKey,80)]=safe}return out}return cleanText(String(value),300)}
