function osintPublicJob(row,revealSelf=false){if(!row)return null;let result=row.result_json?osintParseJson(row.result_json,{}):null;if(result&&typeof result==='object'&&!revealSelf&&Object.prototype.hasOwnProperty.call(result,'recognitionHints')){result={...result};delete result.recognitionHints}return{id:row.id,tool:row.tool,status:row.status,accessLevel:row.access_level,targetReference:String(row.target_hash||'').slice(0,12),purpose:row.lawful_purpose,createdAt:row.created_at,claimedAt:row.claimed_at,completedAt:row.completed_at,expiresAt:row.expires_at,summary:row.result_summary||'',error:row.error_message||'',selfVerified:Boolean(revealSelf),disclosureMode:revealSelf?'verified-self':'standard',result}}
