async function handleOsintListJobs(request,env){const required=await osintRequireMember(request,env);if(required.response)return required.response;const admin=osintIsAdmin(required.auth.member);const rows=admin&&new URL(request.url).searchParams.get('scope')==='all'?await d1All(env.MEMBERS_DB.prepare('SELECT * FROM osint_tool_jobs ORDER BY created_at DESC LIMIT 100')):await d1All(env.MEMBERS_DB.prepare('SELECT * FROM osint_tool_jobs WHERE member_id=? ORDER BY created_at DESC LIMIT 30').bind(required.auth.member.id));const memberHash=await authHash(String(required.auth.member.email||'').trim().toLowerCase());const verified=Boolean(required.auth.member.email_verified_at);const jobs=rows.map(row=>osintPublicJob(row,verified&&row.member_id===required.auth.member.id&&secureEqual(String(row.target_hash||''),memberHash)));return json({ok:true,count:jobs.length,jobs})}
