async function handleOsintRunnerHeartbeat(request,env){if(!osintRunnerAuthorized(request,env))return json({ok:false,error:'Forbidden'},403);const body=await readBody(request);const runnerId=cleanText(body.runnerId||request.headers.get('x-runner-id')||'private-runner',120);const supported=(Array.isArray(body.supportedTools)?body.supportedTools:[]).map(value=>cleanText(value,40)).filter(value=>osintToolPolicies[value]);const now=new Date().toISOString();await env.MEMBERS_DB.prepare('INSERT INTO osint_runner_heartbeats (runner_id,supported_tools_json,version,last_seen_at,metadata_json) VALUES (?,?,?,?,?) ON CONFLICT(runner_id) DO UPDATE SET supported_tools_json=excluded.supported_tools_json,version=excluded.version,last_seen_at=excluded.last_seen_at,metadata_json=excluded.metadata_json').bind(runnerId,JSON.stringify(supported),cleanText(body.version||'',60),now,JSON.stringify({platform:cleanText(body.platform||'',120)})).run();return json({ok:true,runnerId,lastSeenAt:now})}
async function handleOsintRunnerNext(request,env){if(!osintRunnerAuthorized(request,env))return json({ok:false,error:'Forbidden'},403);if(!osintConfigured(env))return json({ok:false,configured:false,error:'OSINT system not configured'},503);const url=new URL(request.url);const requestedTool=cleanText(url.searchParams.get('tool')||'',40);const runnerId=cleanText(request.headers.get('x-runner-id')||'private-runner',120);const now=new Date().toISOString();let row=requestedTool&&osintToolPolicies[requestedTool]?await d1First(env.MEMBERS_DB.prepare("SELECT * FROM osint_tool_jobs WHERE status='queued' AND tool=? AND expires_at>? ORDER BY created_at LIMIT 1").bind(requestedTool,now)):await d1First(env.MEMBERS_DB.prepare("SELECT * FROM osint_tool_jobs WHERE status='queued' AND expires_at>? ORDER BY created_at LIMIT 1").bind(now));if(!row)return json({ok:true,job:null});await env.MEMBERS_DB.prepare("UPDATE osint_tool_jobs SET status='running',claimed_at=?,runner_id=? WHERE id=? AND status='queued'").bind(now,runnerId,row.id).run();row=await d1First(env.MEMBERS_DB.prepare('SELECT * FROM osint_tool_jobs WHERE id=? LIMIT 1').bind(row.id));if(!row||row.status!=='running'||row.runner_id!==runnerId)return json({ok:true,job:null});const target=await osintDecryptTarget(row.target_ciphertext,row.target_iv,env);return json({ok:true,job:{id:row.id,tool:row.tool,target,purpose:row.lawful_purpose,createdAt:row.created_at,expiresAt:row.expires_at}})}
async function handleOsintRunnerResult(request,env,id){if(!osintRunnerAuthorized(request,env))return json({ok:false,error:'Forbidden'},403);const row=await d1First(env.MEMBERS_DB.prepare('SELECT id,member_id,tool,status FROM osint_tool_jobs WHERE id=? LIMIT 1').bind(id));if(!row)return json({ok:false,error:'Job not found'},404);const body=await readBody(request);const safe=osintSanitizeResult(body.result||{},'result',0);const encoded=JSON.stringify(safe||{});if(encoded.length>120000)return json({ok:false,error:'Sanitised result is too large'},413);const now=new Date().toISOString();const summary=cleanText(body.summary||'Tool completed with sanitised results.',600);await env.MEMBERS_DB.prepare("UPDATE osint_tool_jobs SET status='completed',result_json=?,result_summary=?,error_message=NULL,target_ciphertext='',target_iv='',completed_at=? WHERE id=?").bind(encoded,summary,now,id).run();await osintAudit(env,row.member_id,'osint.job.completed',id,{tool:row.tool});return json({ok:true,completed:true})}
async function handleOsintRunnerFail(request,env,id){if(!osintRunnerAuthorized(request,env))return json({ok:false,error:'Forbidden'},403);const row=await d1First(env.MEMBERS_DB.prepare('SELECT id,member_id,tool FROM osint_tool_jobs WHERE id=? LIMIT 1').bind(id));if(!row)return json({ok:false,error:'Job not found'},404);const body=await readBody(request);const now=new Date().toISOString();const error=cleanText(body.error||'Private runner reported a failure.',700);await env.MEMBERS_DB.prepare("UPDATE osint_tool_jobs SET status='failed',error_message=?,target_ciphertext='',target_iv='',completed_at=? WHERE id=?").bind(error,now,id).run();await osintAudit(env,row.member_id,'osint.job.failed',id,{tool:row.tool,error:error.slice(0,120)});return json({ok:true,failed:true})}


/* phase6-market-watchlists-v1: authenticated D1 market watches */
const marketWatchTypes=new Set(['person','institution','issuer','ticker','cik']);
function marketBool(value){return value===true||value===1||value==='1'||String(value||'').toLowerCase()==='true'}
function marketPublicWatch(row){return{id:row.id,targetType:row.target_type,targetKey:row.target_key,targetLabel:row.target_label,alertInsiderTransactions:Boolean(row.alert_insider_transactions),alertInstitutionChanges:Boolean(row.alert_institution_changes),alertNewPositions:Boolean(row.alert_new_positions),alertExits:Boolean(row.alert_exits),minimumReportedValue:row.minimum_reported_value===null||row.minimum_reported_value===undefined?null:Number(row.minimum_reported_value),createdAt:row.created_at,updatedAt:row.updated_at}}
function marketText(value){return String(value||'').toLowerCase().trim()}
function marketFirst(value){return Array.isArray(value)?(value[0]||''):(value||'')}
function marketRecordValue(record){return Number(record.reportedTransactionValue??record.currentValueUsd??record.previousValueUsd??0)||0}
function marketRecordView(record,type){const insider=type==='insider';return{id:cleanText(record.id||record.filingAccession||record.accessionNumber||'',160),kind:insider?'insider-transaction':'institutional-position-change',subject:cleanText(insider?marketFirst(record.reportingOwnerNames)||marketFirst(record.reportingOwners)&&marketFirst(record.reportingOwners).name:record.managerName,180),issuer:cleanText(insider?record.issuer&&record.issuer.name:record.issuerName,180),ticker:cleanText(insider?record.issuer&&record.issuer.ticker:record.ticker,30),action:cleanText(insider?record.transactionCategory||record.transactionCode:record.changeType,80),transactionCode:cleanText(record.transactionCode||'',20),shares:Number(record.shares??record.currentShares??0)||0,previousShares:Number(record.previousShares??0)||0,currentShares:Number(record.currentShares??0)||0,shareChange:Number(record.shareChange??0)||0,reportedValue:marketRecordValue(record),eventDate:cleanText(insider?record.transactionDate:record.currentReportDate,40),filingDate:cleanText(insider?record.filingDate:record.currentFilingDate,40),sourceUrl:cleanText(insider?record.sourceUrl:record.currentSourceUrl||record.sourceUrl,700),evidenceGrade:cleanText(record.evidenceGrade||'A',10),factualStatus:cleanText(record.factualStatus||'official filing',120),established:cleanText(record.establishes||record.established||'',1000),notEstablished:cleanText(record.doesNotEstablish||record.notEstablished||'',1000)}}
async function marketRequireMember(request,env){const auth=await authSessionMember(request,env);if(!auth)return{response:json({ok:false,error:'Authentication required'},401)};if(String(auth.member.status||'active')!=='active')return{response:json({ok:false,error:'Active membership required'},403)};return{auth}}
async function handleMarketWatchlistList(request,env){const required=await marketRequireMember(request,env);if(required.response)return required.response;const rows=await d1All(env.MEMBERS_DB.prepare('SELECT * FROM member_market_watchlists WHERE member_id=? ORDER BY created_at DESC LIMIT 100').bind(required.auth.member.id));return json({ok:true,evidenceBoundary:'Alerts report public filing events. They do not establish motive, current ownership, coordination, investment merit or wrongdoing.',watchlists:rows.map(marketPublicWatch)})}
async function handleMarketWatchlistCreate(request,env){const required=await marketRequireMember(request,env);if(required.response)return required.response;const body=await readBody(request);const targetType=cleanText(body.targetType||'',30).toLowerCase();if(!marketWatchTypes.has(targetType))return json({ok:false,error:'Unsupported watch type'},400);let targetKey=cleanText(body.targetKey||'',120).trim();const targetLabel=cleanText(body.targetLabel||'',160).trim();if(targetType==='ticker')targetKey=targetKey.toUpperCase();if(targetType==='cik')targetKey=targetKey.replace(/\D/g,'').padStart(10,'0');if(!targetKey||targetLabel.length<2)return json({ok:false,error:'Target key and display label are required'},400);let minimum=null;if(body.minimumReportedValue!==null&&body.minimumReportedValue!==undefined&&body.minimumReportedValue!==''){minimum=Number(body.minimumReportedValue);if(!Number.isFinite(minimum)||minimum<0||minimum>1e15)return json({ok:false,error:'Invalid minimum reported value'},400)}const existing=await d1First(env.MEMBERS_DB.prepare('SELECT id FROM member_market_watchlists WHERE member_id=? AND target_type=? AND target_key=? LIMIT 1').bind(required.auth.member.id,targetType,targetKey));const now=new Date().toISOString();if(existing){await env.MEMBERS_DB.prepare('UPDATE member_market_watchlists SET target_label=?,alert_insider_transactions=?,alert_institution_changes=?,alert_new_positions=?,alert_exits=?,minimum_reported_value=?,updated_at=? WHERE id=? AND member_id=?').bind(targetLabel,marketBool(body.alertInsiderTransactions)?1:0,marketBool(body.alertInstitutionChanges)?1:0,marketBool(body.alertNewPositions)?1:0,marketBool(body.alertExits)?1:0,minimum,now,existing.id,required.auth.member.id).run();return json({ok:true,updated:true,id:existing.id})}const count=await d1First(env.MEMBERS_DB.prepare('SELECT COUNT(*) AS count FROM member_market_watchlists WHERE member_id=?').bind(required.auth.member.id));const tier=String(required.auth.member.tier||'free');const limit=tier==='research_pro'?100:tier==='intelligence'?50:tier==='supporter'?25:10;if(Number(count&&count.count||0)>=limit)return json({ok:false,error:'Watchlist limit reached for '+tier+' tier'},429);const id='market-watch-'+crypto.randomUUID();await env.MEMBERS_DB.prepare('INSERT INTO member_market_watchlists (id,member_id,target_type,target_key,target_label,alert_insider_transactions,alert_institution_changes,alert_new_positions,alert_exits,minimum_reported_value,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,required.auth.member.id,targetType,targetKey,targetLabel,marketBool(body.alertInsiderTransactions)?1:0,marketBool(body.alertInstitutionChanges)?1:0,marketBool(body.alertNewPositions)?1:0,marketBool(body.alertExits)?1:0,minimum,now,now).run();if(typeof osintAudit==='function')await osintAudit(env,required.auth.member.id,'market.watch.created',id,{targetType,targetKey});return json({ok:true,created:true,id},201)}
async function handleMarketWatchlistDelete(request,env,id){const required=await marketRequireMember(request,env);if(required.response)return required.response;const row=await d1First(env.MEMBERS_DB.prepare('SELECT id FROM member_market_watchlists WHERE id=? AND member_id=? LIMIT 1').bind(id,required.auth.member.id));if(!row)return json({ok:false,error:'Watch not found'},404);await env.MEMBERS_DB.prepare('DELETE FROM member_market_watchlists WHERE id=? AND member_id=?').bind(id,required.auth.member.id).run();if(typeof osintAudit==='function')await osintAudit(env,required.auth.member.id,'market.watch.deleted',id,{});return json({ok:true,deleted:true})}
async function marketLoadActivity(request,env){if(!env||!env.ASSETS||typeof env.ASSETS.fetch!=='function')return null;try{const url=new URL('/data/market-activity.json',request.url);const response=await env.ASSETS.fetch(new Request(url.toString(),{method:'GET'}));if(!response.ok)return null;return await response.json()}catch{return null}}
function marketMatchesWatch(watch,record,type){const key=marketText(watch.target_key);const ownerNames=(record.reportingOwnerNames||[]).map(marketText);const ownerCiks=(record.reportingOwners||[]).map(item=>marketText(item&&item.cik));const manager=marketText(record.managerName);const managerCik=marketText(record.managerCik);const issuer=marketText(type==='insider'?record.issuer&&record.issuer.name:record.issuerName);const ticker=marketText(type==='insider'?record.issuer&&record.issuer.ticker:record.ticker);const issuerCik=marketText(type==='insider'?record.issuer&&record.issuer.cik:record.issuerCik);if(watch.target_type==='person'&&!ownerNames.some(value=>value===key||value.includes(key)||key.includes(value)))return false;if(watch.target_type==='institution'&&!(manager===key||manager.includes(key)||key.includes(manager)))return false;if(watch.target_type==='issuer'&&!(issuer===key||issuer.includes(key)||key.includes(issuer)))return false;if(watch.target_type==='ticker'&&ticker!==key)return false;if(watch.target_type==='cik'&&![...ownerCiks,managerCik,issuerCik].includes(key))return false;if(watch.minimum_reported_value!==null&&watch.minimum_reported_value!==undefined&&marketRecordValue(record)<Number(watch.minimum_reported_value))return false;if(type==='insider'&&!watch.alert_insider_transactions)return false;if(type==='institution'&&!watch.alert_institution_changes)return false;if(type==='institution'&&record.changeType==='new-position'&&!watch.alert_new_positions)return false;if(type==='institution'&&record.changeType==='exited-position'&&!watch.alert_exits)return false;return true}
async function handleMarketAlerts(request,env){const required=await marketRequireMember(request,env);if(required.response)return required.response;const watches=await d1All(env.MEMBERS_DB.prepare('SELECT * FROM member_market_watchlists WHERE member_id=? ORDER BY created_at DESC LIMIT 100').bind(required.auth.member.id));const activity=await marketLoadActivity(request,env);if(!activity)return json({ok:false,error:'Market activity data unavailable'},503);const candidates=[...(activity.insiderTransactions||[]).map(record=>({record,type:'insider'})),...(activity.positionChanges||activity.institutionalChanges||[]).map(record=>({record,type:'institution'}))];const matches=[];for(const watch of watches){for(const candidate of candidates){if(!marketMatchesWatch(watch,candidate.record,candidate.type))continue;const view=marketRecordView(candidate.record,candidate.type);matches.push({...view,watchId:watch.id,watchLabel:watch.target_label});if(matches.length>=250)break}if(matches.length>=250)break}matches.sort((a,b)=>String(b.eventDate||b.filingDate||'').localeCompare(String(a.eventDate||a.filingDate||'')));const now=new Date().toISOString();for(const match of matches.slice(0,100)){const id='market-alert-'+await authHash(required.auth.member.id+'|'+match.watchId+'|'+match.id+'|dashboard');await env.MEMBERS_DB.prepare("INSERT OR IGNORE INTO market_alert_deliveries (id,member_id,watchlist_id,activity_id,delivery_channel,status,created_at,sent_at) VALUES (?,?,?,?,?,'sent',?,?)").bind(id,required.auth.member.id,match.watchId,match.id,'dashboard',now,now).run().catch(()=>null)}return json({ok:true,generatedAt:now,evidenceBoundary:'These alerts match official filing records to a private member watchlist. A match does not establish motive, present ownership, coordination, investment merit or wrongdoing.',watchCount:watches.length,alertCount:matches.length,alerts:matches.slice(0,200)})}

function isHostileProbePath(pathname=''){return /\/(?:wp-admin|wp-login|xmlrpc\.php|\.env|vendor\/phpunit|cgi-bin|boaform|phpmyadmin|adminer|\.git|config\.php|setup\.php|shell|password|passwd|HNAP1)/i.test(pathname)}
